package com.arslanca.orchestrai.business.abstracts.delivery;

import com.arslanca.orchestrai.business.delivery.composition.DeliveryComposition;
import com.arslanca.orchestrai.business.delivery.layout.IdeRenderedLayout;

/**
 * IDE-specific blueprint delivery strategy.
 * Implementations define how the blueprint is formatted for a specific IDE.
 */
public interface IdeDeliveryStrategy {

  /**
   * Transforms the raw LLM blueprint into an IDE-native file tree.
   *
   * @param composition The blueprint composition payload generated by the
   *                    Composer
   * @return List of IDE-native file nodes (path and content)
   */
  IdeRenderedLayout transform(DeliveryComposition composition);

  /**
   * Returns the name of the IDE supported by this strategy.
   */
  String supportedIde();
}
